-- Role responsibilities reuse existing notification events, never grant operational permissions.
create unique index if not exists notification_role_event_unique on public.notificaciones_reglas(empresa,evento_codigo)
where condiciones->>'origen'='responsabilidades_rol';

create or replace function public.guardar_responsabilidades_rol(p_empresa text,p_rol integer,p_codigos text[],p_esperados text[])
returns void language plpgsql security invoker set search_path=public,pg_temp as $fn$
declare
 role_name text; current_codes text[]; requested text[]; event jsonb; existing public.notificaciones_reglas%rowtype; targets jsonb;
 catalog constant jsonb := '[{"code":"gastos_imputacion_pendiente","module":"Gastos","name":"Imputaciones pendientes de Gastos","description":"Resumen diario en la campana de los responsables. No cambia los permisos de aprobación.","frequency":"Diaria"},{"code":"rrhh_imputacion_pendiente","module":"RRHH","name":"Imputaciones pendientes de RRHH","description":"Resumen diario en la campana de los responsables. No cambia los permisos de aprobación.","frequency":"Diaria"},{"code":"maquinaria_imputacion_pendiente","module":"Maquinaria","name":"Imputaciones pendientes de Maquinaria","description":"Resumen diario en la campana de los responsables. No cambia los permisos de aprobación.","frequency":"Diaria"},{"code":"especialidad_jornada_abierta","module":"Obras","name":"Jornada de especialidad sin cerrar","description":"Recuerda el cierre al responsable designado y a los destinatarios configurados, en días laborales. Hora sugerida: 20:00 de Chile.","frequency":"Diaria"},{"code":"avance_registrado","module":"Obras","name":"Avance registrado","description":"Informa cada nuevo reporte de avance físico.","frequency":"Inmediata"},{"code":"avance_reporte_pendiente","module":"Obras","name":"Reporte de avance diario pendiente","description":"Avisa las obras activas que no han enviado su reporte diario. Un reporte con avance 0 se considera correctamente informado.","frequency":"Diaria"},{"code":"reportes_diarios_pendientes","module":"Obras","name":"Resumen diario de informes pendientes","description":"Consolida cada día las obras que aún deben informar avance o uso de maquinaria.","frequency":"Diaria"},{"code":"resumen_diario_obra","module":"Obras","name":"Resumen diario de obra","description":"Consolida avances, asistencia, incidencias y pendientes del día.","frequency":"Diaria"},{"code":"desviacion_programacion","module":"Obras","name":"Desviación de programación","description":"Alerta cuando el avance real queda bajo el plan.","frequency":"Diaria"},{"code":"partida_proxima_inicio","module":"Obras","name":"Partida próxima a iniciar","description":"Anticipa partidas y recursos que deben quedar liberados.","frequency":"Anticipada"},{"code":"restriccion_last_planner","module":"Obras","name":"Restricción Last Planner pendiente","description":"Alerta compromisos que podrían impedir el inicio de una partida.","frequency":"Diaria"},{"code":"mantenimiento_proximo","module":"Maquinaria","name":"Próximo mantenimiento","description":"Avisa antes de alcanzar la fecha, horómetro o kilometraje de mantención.","frequency":"Anticipada"},{"code":"maquinaria_reporte_pendiente","module":"Maquinaria","name":"Reporte diario de maquinaria pendiente","description":"Avisa cuando una obra con equipos asignados no ha registrado su reporte diario de uso, incluso si el equipo no trabajó.","frequency":"Diaria"},{"code":"mantenimiento_vencido","module":"Maquinaria","name":"Mantenimiento vencido","description":"Escala equipos con mantenimiento pendiente.","frequency":"Diaria"},{"code":"maquinaria_falla_reportada","module":"Maquinaria","name":"Falla de equipo reportada","description":"Informa fallas, detenciones y horas fuera de servicio.","frequency":"Inmediata"},{"code":"maquinaria_reserva_conflicto","module":"Maquinaria","name":"Conflicto o vencimiento de reserva","description":"Advierte conflictos de disponibilidad y reservas próximas.","frequency":"Anticipada"},{"code":"incidente_accidente","module":"Prevención","name":"Incidente o accidente informado","description":"Notificación inmediata de un evento preventivo.","frequency":"Inmediata"},{"code":"prevencion_accion_vencida","module":"Prevención","name":"Acción preventiva vencida","description":"Escala medidas correctivas sin cierre dentro del plazo.","frequency":"Diaria"},{"code":"prevencion_registro_recibido","module":"Prevención","name":"Nuevo registro preventivo","description":"Informa inspecciones, PARE, AST y registros recibidos.","frequency":"Inmediata"},{"code":"prevencion_cumplimiento_pendiente","module":"Prevención","name":"Cumplimiento preventivo pendiente","description":"Avisa al usuario responsable y escala a los destinatarios configurados cuando un formulario diario, semanal o mensual no fue completado al vencimiento.","frequency":"Diaria"},{"code":"prevencion_cumplimiento_bajo","module":"Prevención","name":"Cumplimiento preventivo bajo meta","description":"Alerta cuando una obra o actividad cae bajo el estándar configurado.","frequency":"Semanal"},{"code":"rdi_pendiente","module":"Calidad","name":"RDI pendiente de respuesta","description":"Recuerda solicitudes RDI sin respuesta dentro del plazo.","frequency":"Diaria"},{"code":"recepcion_observada","module":"Calidad","name":"Recepción observada o rechazada","description":"Informa observaciones y rechazos de partidas.","frequency":"Inmediata"},{"code":"calidad_nc_vencida","module":"Calidad","name":"No conformidad vencida","description":"Escala no conformidades que no han sido cerradas.","frequency":"Diaria"},{"code":"calidad_recepcion_solicitada","module":"Calidad","name":"Recepción de partida solicitada","description":"Avisa que existe un protocolo pendiente de revisión.","frequency":"Inmediata"},{"code":"estado_pago_cambio","module":"Estados de pago","name":"Cambio de estado de pago","description":"Informa envíos, observaciones, aprobaciones y pagos.","frequency":"Inmediata"},{"code":"estado_pago_documentos_pendientes","module":"Estados de pago","name":"Documentación contractual pendiente","description":"Recuerda documentos obligatorios pendientes o rechazados.","frequency":"Diaria"},{"code":"estado_pago_factura_pendiente","module":"Estados de pago","name":"Factura pendiente de emisión o pago","description":"Da seguimiento a la factura asociada al estado de pago.","frequency":"Anticipada"},{"code":"ep_subcontrato_documentos_pendientes","module":"Subcontratos","name":"Documentos pendientes del estado de pago","description":"Avisa que el expediente obligatorio está incompleto o pendiente de revisión.","frequency":"Diaria"},{"code":"ep_subcontrato_documento_observado","module":"Subcontratos","name":"Documento observado o rechazado","description":"Informa al responsable cuando un antecedente debe corregirse.","frequency":"Inmediata"},{"code":"ep_subcontrato_expediente_aprobado","module":"Subcontratos","name":"Expediente documental aprobado","description":"Informa que el estado de pago ya puede continuar a aprobación y facturación.","frequency":"Inmediata"},{"code":"factura_vencimiento","module":"Facturación","name":"Factura próxima a vencer","description":"Avisa documentos por vencer o vencidos.","frequency":"Anticipada"},{"code":"acreditacion_vencimiento","module":"Acreditaciones","name":"Acreditación próxima a vencer","description":"Controla documentos de empresa, personal y equipos.","frequency":"Anticipada"},{"code":"stock_minimo","module":"Bodega","name":"Stock mínimo","description":"Alerta cuando un artículo alcanza su nivel de reposición.","frequency":"Inmediata"},{"code":"bodega_quiebre_stock","module":"Bodega","name":"Quiebre de stock","description":"Alerta productos sin disponibilidad para la operación.","frequency":"Inmediata"},{"code":"bodega_transferencia_pendiente","module":"Bodega","name":"Transferencia pendiente de recepción","description":"Recuerda movimientos entre bodegas aún no confirmados.","frequency":"Diaria"},{"code":"bodega_guia_sin_conciliar","module":"Bodega","name":"Guía de despacho sin conciliar","description":"Advierte guías que no están asociadas correctamente a movimientos o DTE.","frequency":"Diaria"},{"code":"rrhh_contrato_vencimiento","module":"Recursos Humanos","name":"Contrato próximo a vencer","description":"Anticipa vencimientos contractuales de trabajadores.","frequency":"Anticipada"},{"code":"rrhh_documento_vencimiento","module":"Recursos Humanos","name":"Documento laboral próximo a vencer","description":"Controla documentos obligatorios del trabajador.","frequency":"Anticipada"},{"code":"rrhh_brecha_dotacion","module":"Recursos Humanos","name":"Brecha de dotación proyectada","description":"Avisa cargos requeridos que aún no tienen cobertura.","frequency":"Semanal"},{"code":"rrhh_ausencia_critica","module":"Recursos Humanos","name":"Ausencia o dotación crítica","description":"Alerta ausencias que afectan la dotación mínima de una obra.","frequency":"Inmediata"},{"code":"gasto_pendiente","module":"Gastos","name":"Rendición pendiente de aprobación","description":"Informa rendiciones que requieren revisión.","frequency":"Diaria"},{"code":"gasto_observado","module":"Gastos","name":"Rendición observada o rechazada","description":"Informa al responsable que debe corregir una rendición.","frequency":"Inmediata"},{"code":"dte_recibido","module":"Facturación","name":"Nuevo DTE recibido","description":"Informa la recepción de facturas, notas o guías electrónicas.","frequency":"Inmediata"},{"code":"dte_sin_centro_gestion","module":"Facturación","name":"DTE sin centro de gestión","description":"Alerta documentos que aún no pueden imputarse a una obra o centro.","frequency":"Diaria"},{"code":"libro_obra_pendiente","module":"Libro de obra","name":"Folio pendiente de acción","description":"Recuerda autorizaciones, respuestas y observaciones pendientes.","frequency":"Diaria"}]'::jsonb;
begin
 if auth.uid() is null or not private.obraxis_actor_can_manage_company(p_empresa) then raise exception 'No tienes permiso para configurar roles de esta empresa'; end if;
 perform pg_advisory_xact_lock(hashtextextended('role-responsibilities:'||p_empresa,0));
 select nombre into role_name from public.roles where id=p_rol and empresa=p_empresa and not coalesce(archivado,false);
 if role_name is null then raise exception 'Rol no disponible en esta empresa'; end if;
 select coalesce(array_agg(distinct c order by c),'{}') into requested from unnest(coalesce(p_codigos,'{}')) c;
 if exists(select 1 from unnest(requested)c where not exists(select 1 from jsonb_array_elements(catalog)e where e->>'code'=c)) then raise exception 'Responsabilidad desconocida'; end if;
 select coalesce(array_agg(distinct evento_codigo order by evento_codigo),'{}') into current_codes from public.notificaciones_reglas where empresa=p_empresa and activa and condiciones->>'origen'='responsabilidades_rol' and destinatarios_roles ? role_name;
 if current_codes is distinct from (select coalesce(array_agg(distinct c order by c),'{}') from unnest(coalesce(p_esperados,'{}'))c) then raise exception 'Otro administrador cambió este rol. Recarga antes de guardar'; end if;
 for event in select value from jsonb_array_elements(catalog) loop
  select * into existing from public.notificaciones_reglas where empresa=p_empresa and evento_codigo=event->>'code' and (condiciones->>'origen'='responsabilidades_rol' or evento_codigo='prevencion_cumplimiento_pendiente') order by (condiciones->>'origen'='responsabilidades_rol') desc nulls last limit 1;
  if existing.condiciones->>'origen' is distinct from 'responsabilidades_rol' and not (event->>'code'=any(requested)) then continue; end if;
  targets:=coalesce(existing.destinatarios_roles,'[]'::jsonb)-role_name;
  if event->>'code'=any(requested) then targets:=targets||jsonb_build_array(role_name); end if;
  if existing.id is null then
   insert into public.notificaciones_reglas(empresa,nombre,evento_codigo,modulo,descripcion,destinatarios_roles,destinatarios_usuarios,correos_adicionales,canal_email,canal_plataforma,canal_push,frecuencia,hora_envio,condiciones,activa,creado_por)
   values(p_empresa,event->>'name',event->>'code',event->>'module',event->>'description',targets,'[]','[]',false,true,false,event->>'frequency','18:00',jsonb_build_object('origen','responsabilidades_rol','alcance_tipo','asignadas'),jsonb_array_length(targets)>0,auth.uid()::text);
  else
   update public.notificaciones_reglas set destinatarios_roles=targets,destinatarios_usuarios='[]',correos_adicionales='[]',obra_nombre=null,
    condiciones=coalesce(condiciones,'{}')||jsonb_build_object('origen','responsabilidades_rol','alcance_tipo','asignadas','obras_seleccionadas','[]'::jsonb),
    activa=jsonb_array_length(targets)>0,canal_email=false,canal_plataforma=true,updated_at=now() where id=existing.id;
  end if;
 end loop;
end $fn$;
revoke all on function public.guardar_responsabilidades_rol(text,integer,text[],text[]) from public,anon;
grant execute on function public.guardar_responsabilidades_rol(text,integer,text[],text[]) to authenticated;

-- Explicitly requested: leave old direct Lonco duties unchecked; keep rules and delivery history.
update public.notificaciones_reglas set activa=false,updated_at=now()
where empresa='EMINSG' and evento_codigo in ('gastos_imputacion_pendiente','maquinaria_imputacion_pendiente')
 and destinatarios_usuarios @> '["19"]'::jsonb and obra_nombre='IP-EDIFICO L LONCO'
 and condiciones->>'alcance_tipo'='seleccionadas'
 and condiciones->>'origen' is distinct from 'responsabilidades_rol';

-- Final recipient boundary for role-managed notices, including existing producers.
create or replace function private.guard_role_responsibility_delivery()
returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
declare rule public.notificaciones_reglas%rowtype;
begin
 select * into rule from public.notificaciones_reglas where id=new.regla_id;
 if rule.condiciones->>'origen' is distinct from 'responsabilidades_rol' then return new; end if;
 if not rule.activa or nullif(trim(new.obra_nombre),'') is null then return null; end if;
 if not exists (
 select 1 from public.usuarios u
 join public.roles r on r.empresa=u.empresa and r.nombre=u.rol and not coalesce(r.archivado,false)
 where u.empresa=rule.empresa and u.empresa=new.empresa
 and rule.destinatarios_roles ? u.rol
 and lower(trim(new.destinatario)) in (lower(u.id::text),lower(u.usuario),lower(u.correo))
 and exists(select 1 from regexp_split_to_table(coalesce(u.obras,''),',') w where lower(trim(w)) in ('todas',lower(trim(new.obra_nombre))))
 ) then return null; end if;
 return new;
end $$;
drop trigger if exists guard_role_responsibility_delivery on public.notificaciones_entregas;
create trigger guard_role_responsibility_delivery before insert on public.notificaciones_entregas for each row execute function private.guard_role_responsibility_delivery();

